style.css:
@-moz-document url-prefix("https://www.google.com") {
/* Cor de fundo da barra de título das abas */
    .gb_Bb {
        background-color: #F7E0F9 !important;
    }

    /* Imagem de fundo do Google */
    body {
        background-image: url('https://i.pinimg.com/736x/a5/34/fb/a534fb2876910534c67e3fe299e3ca87.jpg');
        background-size: cover;
        background-position: center;
        background-attachment: fixed;
    }

    /* Estilo da barra de pesquisa do Google */
    .gLFyf {
        background-color: rgba(255, 255, 255, 0.8) !important;
        border-radius: 5px;
    }

    /* Links no Google */
    a {
        color: #F7E0F9 !important;
    }

    /* Cor do texto das abas */
    .gb_8a {
        color: #F7E0F9 !important;
    }
}
